57	    // ---------- 拆分主流程 ----------
58	
59	    @Test
60	    void happySplit_parentBecomesSplit_childrenInheritAndStartQuarantined() throws Exception {
61	        String parent = "BK-SP-P-" + unique();
62	        createBatch(parent, List.of("外观", "含量"), 201);
63	        releaseBatch(parent, "insp-1");
64	
65	        List<String> childKeys = List.of("BK-SP-C1-" + unique(), "BK-SP-C2-" + unique(),
66	                "BK-SP-C3-" + unique());
67	        MvcResult result = split(parent, "CK-SPLIT-1",
68	                childKeys.stream().map(k -> new String[]{k, "LOT-" + k.substring(k.length() - 4)})
69	                        .toList(), 201);
