71	        JsonNode body = objectMapper.readTree(result.getResponse().getContentAsString());
72	        assertEquals(parent, body.path("parentBatchKey").asText());
73	        assertEquals("SPLIT", body.path("parentStatus").asText());
74	        assertEquals(3, body.path("children").size());
75	        for (int i = 0; i < 3; i++) {
76	            JsonNode child = body.path("children").get(i);
77	            assertEquals(childKeys.get(i), child.path("batchKey").asText());
78	            assertEquals("QUARANTINED", child.path("status").asText());
79	            assertEquals("PROD-1", child.path("productCode").asText());
80	            assertEquals("2026-01-02T03:04:05Z", child.path("producedAt").asText());
81	            assertEquals(List.of("外观", "含量"), objectMapper.convertValue(
82	                    child.path("requiredTests"), objectMapper.getTypeFactory()
83	                            .constructCollectionType(List.class, String.class)));
84	        }
85	
86	        // 父批 SPLIT 不再可用；子批初始隔离、出现在可用列表
