566	     * 让批次走完 检验 PASS + 双角色批准 进入 RELEASED。
567	     */
568	    private void releaseBatch(String batchKey, String inspector) throws Exception {
569	        MvcResult history = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
