                    .orElseThrow(() -> ApiException.conflict(
                            "批次无 ACTIVE 召回记录，不可申请解除: " + batchKey));
            if (recall.version() != req.recallVersion()) {
                throw ApiException.conflict("召回版本不匹配：当前 ACTIVE 召回版本为 "
