        retest(child, "RT-HP-2", "PASS", "qa-2", "CK-RT-2", 201);
        retest(sibling, "RT-HP-3", "PASS", "qa-3", "CK-RT-3", 201);

        // 申请：复检集合乱序且含重复，服务端去重并规范排序
        MvcResult applied = applyRelease(root, "mgr-1", "RK-HP-1", 1, "更换供应商并全检",
